# =====================================================================
# cavallo_horse_icon_patch.ps1
#
# Replaces the app icon and the launch (splash) screen with the new
# Cavallo horse emblem ("Cavallo Horse Emblem App Icon.png"), on Android and iOS.
#
#   Android : legacy launcher icon, adaptive icon (foreground + background),
#             splash logo for Android 11 and older, splash colour.
#   iOS     : the whole AppIcon set (every size) and the launch image.
#
# No Dart file is touched, so no test and no golden image changes.
# Colours, fonts, layouts and texts of the app stay exactly as they are.
#
# Run from the Flutter project root (the folder with pubspec.yaml):
#     powershell -ExecutionPolicy Bypass -File .\cavallo_horse_icon_patch.ps1
# Preview only, no file is written:
#     powershell -ExecutionPolicy Bypass -File .\cavallo_horse_icon_patch.ps1 -DryRun
#
# Safe to run twice: files that are already up to date are reported and skipped.
# To undo everything:  git checkout -- android ios
# =====================================================================
param([switch]$DryRun)

$ErrorActionPreference = 'Stop'
$root = (Get-Location).ProviderPath
$utf8 = New-Object System.Text.UTF8Encoding($false)
$script:changed = 0
$script:failed  = New-Object 'System.Collections.Generic.List[string]'

function Say([string]$msg, [string]$color = 'Gray') { Write-Host $msg -ForegroundColor $color }
function Get-Full([string]$rel) { return [System.IO.Path]::GetFullPath((Join-Path $root $rel)) }
function Norm([string]$s) { return $s.Replace("`r`n", "`n") }

# Writes a whole text file (XML). Keeps the line endings the file already has.
function Add-NewText([string]$rel, [string]$content) {
    $full = Get-Full $rel
    $content = (Norm $content).TrimEnd("`n") + "`n"
    $crlf = $false
    if (Test-Path -LiteralPath $full) {
        $raw = [System.IO.File]::ReadAllText($full)
        $crlf = $raw.Contains("`r`n")
        if ((Norm $raw) -ceq $content) { Say "  =  $rel (already up to date)"; return }
    }
    if (-not $DryRun) {
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($full))
        $out = $content
        if ($crlf) { $out = $out.Replace("`n", "`r`n") }
        [System.IO.File]::WriteAllText($full, $out, $utf8)
    }
    Say "  ~  $rel" 'Cyan'
    $script:changed++
}

# Writes a binary file (PNG) from base64 text.
function Add-Binary([string]$rel, [string]$b64) {
    $b64 = $b64 -replace '\s+', ''
    $full = Get-Full $rel
    $existed = Test-Path -LiteralPath $full
    if ($existed) {
        if ([System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes($full)) -ceq $b64) { Say "  =  $rel (already up to date)"; return }
    }
    if (-not $DryRun) {
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($full))
        [System.IO.File]::WriteAllBytes($full, [System.Convert]::FromBase64String($b64))
    }
    if ($existed) { Say "  ~  $rel" 'Cyan' } else { Say "  +  $rel" 'Green' }
    $script:changed++
}

function Step([string]$title, [scriptblock]$body) {
    Say ''
    Say $title 'White'
    & $body
}
function Try-Do([string]$what, [scriptblock]$body) {
    try { & $body } catch { Say "  !  $what : $($_.Exception.Message)" 'Red'; $script:failed.Add("$what : $($_.Exception.Message)") }
}

# ---------------------------------------------------------------- checks
if (-not (Test-Path (Join-Path $root 'pubspec.yaml')) -or -not (Test-Path (Join-Path $root 'lib'))) {
    Say 'STOP: run this from the Flutter project root (the folder that holds pubspec.yaml and lib\).' 'Red'; exit 1
}
if ([System.IO.File]::ReadAllText((Join-Path $root 'pubspec.yaml')) -notmatch '(?m)^name:\s*social_commerce_app\s*$') {
    Say 'STOP: pubspec.yaml is not the social_commerce_app project.' 'Red'; exit 1
}
foreach ($need in @('android/app/src/main/res', 'ios/Runner/Assets.xcassets/AppIcon.appiconset')) {
    if (-not (Test-Path (Get-Full $need))) {
        Say "STOP: $need not found. The android and ios folders must be in the project." 'Red'; exit 1
    }
}
if ($DryRun) { Say '*** DRY RUN - no file will be written ***' 'Yellow' }

Step '1/3  Android: splash colour and adaptive icon definition' {
    Try-Do 'android/app/src/main/res/values/ic_launcher_background.xml' { Add-NewText 'android/app/src/main/res/values/ic_launcher_background.xml' @'
<?xml version="1.0" encoding="utf-8"?>
<!-- Cavallo splash colour: the average blue of the horse icon.
     Used by the launch screen (Android 11 and older) and the Android 12+ system splash. -->
<resources>
    <color name="ic_launcher_background">#093CC8</color>
</resources>
'@ }
    Try-Do 'android/app/src/main/res/mipmap-anydpi-v26/ic_launcher.xml' { Add-NewText 'android/app/src/main/res/mipmap-anydpi-v26/ic_launcher.xml' @'
<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@mipmap/ic_launcher_background"/>
    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>
</adaptive-icon>
'@ }
}

Step '2/3  Android: launcher icon, adaptive icon layers, splash logo' {
